package android.os;import java.util.*;public class Handler {static class Job {long at;Runnable r;Job(long a,Runnable x){at=a;r=x;}}private static final List<Job> jobs=new ArrayList<Job>();public Handler(Looper l){}public boolean post(Runnable r){return postDelayed(r,0);}public boolean postDelayed(Runnable r,long d){synchronized(jobs){jobs.add(new Job(SystemClock.time+d,r));}return true;}public void removeCallbacks(Runnable r){synchronized(jobs){for(java.util.Iterator<Job> it=jobs.iterator();it.hasNext();)if(it.next().r==r)it.remove();}}public static void pump(){for(int n=0;n<100;n++){Job found=null;synchronized(jobs){for(Job j:jobs)if(j.at<=SystemClock.time){found=j;break;}if(found!=null)jobs.remove(found);}if(found==null)return;found.r.run();}}public static void clear(){synchronized(jobs){jobs.clear();}}}
